package com.makers.loans;
import com.makers.loans.dto.*; import com.makers.loans.entity.*; import com.makers.loans.repository.*; import com.makers.loans.security.JwtService; import com.makers.loans.service.AuthService; import org.junit.jupiter.api.*; import org.mockito.*; import org.springframework.security.crypto.password.PasswordEncoder; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class AuthServiceTest { @Mock UserRepository repo; @Mock PasswordEncoder encoder; @Mock JwtService jwt; @InjectMocks AuthService service; @BeforeEach void setup(){MockitoAnnotations.openMocks(this);}
 @Test void registraUsuario(){when(repo.existsByEmail("usuario@test.com")).thenReturn(false);when(encoder.encode("123456")).thenReturn("hash");when(repo.save(any(User.class))).thenAnswer(i->i.getArgument(0));when(jwt.generate(anyString(),anyString())).thenReturn("token");AuthResponse r=service.register(new RegisterRequest("usuario@test.com","123456"));assertEquals("token",r.token());assertEquals("USER",r.role());verify(repo).save(any(User.class));}}
